import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"最优子结构与重叠","description":"","frontmatter":{"title":"最优子结构与重叠","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/opt-substructure.md","filePath":"cs/opt-substructure.md","lastUpdated":1789023840000}'),c={name:"cs/opt-substructure.md"};function h(u,a,m,A,_,B){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="最优子结构与重叠" tabindex="-1">最优子结构与重叠 <a class="header-anchor" href="#最优子结构与重叠" aria-label="Permalink to &quot;最优子结构与重叠&quot;">​</a></h1><div class="epigraph"><p>最优解含有某子问题的最优解；同一子问题在递归树里反复出现，才值得制成一张表。</p><footer>—— 据 Bellman, Dynamic Programming, 1957；CLRS 第 15 章整理</footer></div><p>上一课<a href="/cs/dynamic-programming">动态规划</a>已经把状态、转移、填表说成一套。钢条与 LCS 当了骨架，背包细节留给后课。本课不重画 DAG 填表序。缺口是把两条性质拆开钉死：<strong>最优子结构</strong>何时成立、<strong>重叠</strong>与分治的不相交有何不同——没有它们，表是空的或指数仍在。后课用容量把状态写成具体的 \\(dp[i][w]\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最优子结构：原问题最优解里，对选中的那一次切分，左右（或剩余）必须是对应子问题的最优。证明通常用切割：若某块不是最优，换上更优块，原解变好，矛盾。失败典型：图上最长<strong>简单</strong>路——子路加边可能重复顶点，子路最优加起来不必简单，也不必全局最长。有环正权时「最优」甚至无界。缺口不是再解释 \\(\\min/\\max\\)，而是先问能不能切。</p><p>重叠：切法有多种，不同切法问到同一 \\((i,j)\\)。分治归并的左右区间不相交，备忘无收益。DP 故意让区间、前缀、容量被多次引用。没有重叠，指数递归仍可能正确，只是不必填表。</p><h3 id="子结构不是「能递归」" tabindex="-1">子结构不是「能递归」 <a class="header-anchor" href="#子结构不是「能递归」" aria-label="Permalink to &quot;子结构不是「能递归」&quot;">​</a></h3><p>DFS、快排都递归，没有「子答案必须最优」。贪心也要子结构，但另加「只需试一种切」。本课两条都要，且默认枚举切。</p><p><span class="marginnote">Bellman 的最优化原理即子结构。CLRS 15.3 专节讲何时成立。本课把它从「DP 总则」里抽出来，避免背包课再从原理讲起。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义子问题族（前缀、区间、点 \\(v\\) 的最短路）。证明：最优解选定一项转移后，剩余实例的最优可粘回。数清不同子问题个数；若多项式且每个多项式转移，则多项式。若个数指数（子集），算法可以正确但不在 P——<a href="/cs/p-vs-np">P 与 NP</a> 再命名。</p>',11)),(e(),n(E,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CUT%5B%22%E9%80%89%E5%AE%9A%E4%B8%80%E6%AC%A1%E5%88%87%22%5D%20--%3E%20OPTS%5B%22%E5%89%A9%E4%BD%99%E5%BF%85%E9%A1%BB%E6%9C%80%E4%BC%98%22%5D%0A%20%20OPTS%20--%3E%20OV%5B%22%E5%90%8C%E4%B8%80%E5%AD%90%E9%97%AE%E9%A2%98%E5%A4%9A%E6%AC%A1%E5%87%BA%E7%8E%B0%22%5D%0A%20%20OV%20--%3E%20TAB%5B%22%E5%A1%AB%E8%A1%A8%22%5D%0A%20%20OPTS%20--%3E%20FAIL%5B%22%E7%AE%80%E5%8D%95%E6%9C%80%E9%95%BF%E8%B7%AF%EF%BC%9A%E5%88%87%E5%AE%8C%E4%B8%8D%E5%86%8D%E5%90%88%E6%B3%95%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>无重叠 → 退回<a href="/cs/divide-conquer">分治</a>。无子结构 → 不要 DP。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最短路（无负环）有子结构：最短路的子路是最短路。背包：用或不用第 \\(i\\) 件，剩余容量上的最优。区间：最优在某处切开，两段区间最优。后课背包把「容量」写成一维；本课只要求会检查这两条。</p><p>重叠用备忘或自底向上等价：拓扑序保证每个状态在依赖之后算。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 0-1 转移的滚动数组，不引入伪多项式这个词的完整讨论（背包课会用 \\(W\\)）。不证 NPC。后课默认：先问子结构与重叠，再开表。容量与三种背包是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最优子结构 = 切完剩余仍最优；最长简单路是反例。</li><li>重叠 = 子问题重复；无重叠则不必 DP。</li><li>表的大小下一课用背包实例化。</li><li>出处：Bellman, 1957；CLRS 第 15.3 节。</li></ul>',8))])}const D=s(c,[["render",h]]);export{f as __pageData,D as default};
